begin;
alter table admin_reset_logs drop constraint if exists admin_reset_logs_scope_check;
alter table admin_reset_logs add constraint admin_reset_logs_scope_check check(scope in('ALL_CLAIMS','ALL_SPIN_DATA'));
create or replace function admin_reset_all_spin_data(p_campaign text,p_reason text,p_admin_user uuid,p_confirmation text) returns jsonb language plpgsql security definer set search_path=public as $$declare c campaigns;affected_spins int;affected_participants int;restored_units int;new_version bigint;begin if p_confirmation<>'DELETE ALL SPIN DATA' then raise exception 'CONFIRMATION_REQUIRED';end if;if char_length(trim(p_reason))<3 then raise exception 'REASON_REQUIRED';end if;if not exists(select 1 from admin_users where user_id=p_admin_user)then raise exception 'ADMIN_FORBIDDEN';end if;select * into c from campaigns where code=p_campaign for update;if not found then raise exception 'CAMPAIGN_NOT_FOUND';end if;perform 1 from spins where campaign_id=c.id for update;update prize_units set status='AVAILABLE',awarded_at=null,participant_id=null,spin_id=null where campaign_id=c.id and spin_id is not null;get diagnostics restored_units=row_count;delete from spins where campaign_id=c.id;get diagnostics affected_spins=row_count;delete from participants p where p.campaign_id=c.id and not exists(select 1 from spins s where s.participant_id=p.id);get diagnostics affected_participants=row_count;update campaigns set inventory_version=inventory_version+1 where id=c.id returning inventory_version into new_version;insert into admin_reset_logs(campaign_id,admin_user_id,scope,affected_count,reason)values(c.id,p_admin_user,'ALL_SPIN_DATA',affected_spins,trim(p_reason));return jsonb_build_object('ok',true,'affected_spins',affected_spins,'affected_participants',affected_participants,'restored_available',restored_units,'inventory_version',new_version,'scope','ALL_SPIN_DATA');end$$;
revoke all on function admin_reset_all_spin_data(text,text,uuid,text) from public,anon,authenticated;
grant execute on function admin_reset_all_spin_data(text,text,uuid,text) to service_role;
commit;
